// /app/craps/replay-fetch.js — where the sealed replay artifacts actually come from.
//
// In chain mode (the database-free deployment) there is nothing to fetch: `chainReplayFetch`
// reconstructs the pointer, manifest, featured seats and shards in a worker from chain inputs,
// through the same verified pure engine, and this module never touches the network.
//
// Everything below that branch is the legacy hosted path, kept only for a non-chain profile. It
// was same-origin on the deployed site via a Cloudflare Pages Function at `/craps/replays/v1/*`
// that proxied the database API, which read the objects out of R2. That Function was DELETED
// 2026-09-22 along with its jackpot twin: both fronted degenerus-db.fly.dev, which no longer
// exists, so both could only 502. Reviving a hosted profile means reviving the Function with it —
// today a relative path under `/craps/` resolves to nothing on Pages.

import { API_BASE } from '../app/constants.js';
import { CHAIN } from '../app/chain-config.js';

const LOCAL_HOSTS = new Set(['localhost', '127.0.0.1', '[::1]']);

/** '' on the deployed site; the hosted API's game prefix on a local static server. */
export function crapsReplayFetchBase(hostname = globalThis.location?.hostname) {
  return LOCAL_HOSTS.has(String(hostname ?? '')) ? `${API_BASE}/game` : '';
}

// Same deadline api.js gives every indexer read. A replay pointer that never
// answers used to hold app-craps-entry's replay-load flag open for the rest of
// the session, which parks every later replay poll and the "watch replay" tray.
export const CRAPS_REPLAY_FETCH_TIMEOUT_MS = 20_000;

/** Drop-in `fetchImpl` for `loadCrapsReplay` / `openCrapsReplayTable`. */
export function crapsReplayFetch(path, init) {
  if (CHAIN.readMode === 'chain') return import('../chain/craps.js').then(({ chainReplayFetch }) => chainReplayFetch(path, init));
  const signal = init?.signal
    ?? (typeof AbortSignal !== 'undefined' && typeof AbortSignal.timeout === 'function'
      ? AbortSignal.timeout(CRAPS_REPLAY_FETCH_TIMEOUT_MS)
      : undefined);
  return fetch(`${crapsReplayFetchBase()}${path}`, signal ? { ...init, signal } : init);
}
